export async function onRequest(context) {
  const url = new URL(context.request.url);
  const go = (path, code = 301) => Response.redirect(new URL(path, url.origin).toString(), code);

  const p = url.searchParams.get("p") || url.searchParams.get("page_id");
  if (p) {
    const id = p.replace(/\.html$/, "");
    return ID_MAP[id] ? go(ID_MAP[id]) : go("/", 302);
  }
  const cat = url.searchParams.get("cat");
  if (cat) return CAT_MAP[cat] ? go(CAT_MAP[cat]) : go("/", 302);
  const tag = url.searchParams.get("tag");
  if (tag) return TAG_MAP[tag] ? go(TAG_MAP[tag]) : go("/", 302);
  const author = url.searchParams.get("author");
  if (author) return AUTHOR_MAP[author] ? go(AUTHOR_MAP[author]) : go("/", 302);
  if (url.searchParams.has("s") || url.searchParams.has("m") || url.searchParams.has("attachment_id")) return go("/", 302);

  const full = url.pathname + url.search;
  if (QUERY_REDIRECTS[full]) return go(QUERY_REDIRECTS[full]);

  const m = url.pathname.match(/index\.html(?:%3F|\?)p=(\d+)\.html$/i);
  if (m) return ID_MAP[m[1]] ? go(ID_MAP[m[1]]) : go("/", 302);
  return context.next();
}
